        driver.findElement(By.xpath("//div[@class='modal-dialog'][contains(.,'This note will be moved to trash')]" + "//div[@class='modal-footer']//button[contains(.,'OK')]")).click();
        ZeppelinITUtils.sleep(100, true);
        LOG.info("testCreateNotebook Test executed");
    } catch (Exception e) {
        handleException("Exception in ZeppelinIT while testAngularDisplay ", e);
    }
}

