@Test
public void testAutoRestartInterpreterAfterSchedule() throws InterruptedException, IOException {
    // create a note and a paragraph
    Note note = notebook.createNote(anonymous);
    factory.setInterpreters(anonymous.getUser(), note.getId(), factory.getDefaultInterpreterSettingList());
    Paragraph p = note.addParagraph(AuthenticationInfo.ANONYMOUS);
    Map config = new HashMap<>();
    p.setConfig(config);
    p.setText("sleep 1000");
    Paragraph p2 = note.addParagraph(AuthenticationInfo.ANONYMOUS);
    p2.setConfig(config);
    p2.setText("%mock2 sleep 500");
    // set cron scheduler, once a second
    config = note.getConfig();
    config.put("enabled", true);
    config.put("cron", "1/3 * * * * ?");
    config.put("releaseresource", true);
    note.setConfig(config);
    notebook.refreshCron(note.getId());
    MockInterpreter1 mock1 = ((MockInterpreter1) (((ClassloaderInterpreter) ((LazyOpenInterpreter) factory.getInterpreter(anonymous.getUser(), note.getId(), "mock1")).getInnerInterpreter()).getInnerInterpreter()));
    MockInterpreter2 mock2 = ((MockInterpreter2) (((ClassloaderInterpreter) ((LazyOpenInterpreter) factory.getInterpreter(anonymous.getUser(), note.getId(), "mock2")).getInnerInterpreter()).getInnerInterpreter()));
    // wait until interpreters are started
    while (!mock1.isOpen() || !mock2.isOpen()) {
        Thread.yield();
    }
    // wait until interpreters are closed
    while (mock1.isOpen() || mock2.isOpen()) {
        Thread.yield();
    }
    // remove cron scheduler.
    config.put("cron", null);
    note.setConfig(config);
    notebook.refreshCron(note.getId());
    // make sure all paragraph has been executed
    assertNotNull(p.getDateFinished());
    assertNotNull(p2.getDateFinished());
    notebook.removeNote(note.getId(), anonymous);
}

